(()=>{document.querySelectorAll('.reactions button').forEach(btn=>{btn.addEventListener('click',()=>{const wrap=btn.closest('.reactions');const data=new URLSearchParams({action:'aziume_react',nonce:aziumeHumor.nonce,post_id:wrap.dataset.post,reaction:btn.dataset.reaction});fetch(aziumeHumor.ajaxUrl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:data.toString()}).then(r=>r.json()).then(res=>{if(res.success){btn.querySelector('span').textContent=res.data.count}})})});const darkPref=localStorage.getItem('aziume-dark');if(darkPref==='1'){document.documentElement.style.setProperty('--bg','#111');document.documentElement.style.setProperty('--text','#eee')}})();
